-- Migration 0074: the search index is rewritten only when a name changes.
--
-- Each *_search_update trigger deleted the row's entry and wrote it again
-- whenever the name or title was set, changed or not. Deleting from the
-- FTS5 index by entity_id reads the whole index (82,000 entries), and an
-- import sets every song's title as it fills gaps: 737 times on 15 Nov,
-- 61 million rows. Now only a real rename does it. The triggers are 0044's
-- with a WHEN clause added (generated: the expression is long).

DROP TRIGGER artist_search_update;
CREATE TRIGGER artist_search_update AFTER UPDATE OF name ON artist WHEN OLD.name IS NOT NEW.name
BEGIN
