    INSERT INTO search_index (name, kind, entity_id) SELECT CASE WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(a.name, '''', ''), '’', ''), '‘', ''), 'ʼ', ''), '$', 's'), '.', ''), ',', ''), '-', ''), '/', ''), '\', ''), '!', ''), '&', ''), '*', ''), '+', ''), ':', ''), ';', ''), '?', ''), '@', ''), '#', ''), '(', ''), ')', ''), '[', ''), ']', ''), '"', ''), '“', ''), '”', ''), '_', ''), '~', ''), '…', ''), '–', ''), '—', ''), '·', ''), '|', ''), '%', ''), '^', ''), '=', ''), '<', ''), '>', ''), ' ', '') <> replace(replace(replace(replace(a.name, '''', ''), '’', ''), '‘', ''), 'ʼ', '') THEN replace(replace(replace(replace(a.name, '''', ''), '’', ''), '‘', ''), 'ʼ', '') || ' ' || replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(a.name, '''', ''), '’', ''), '‘', ''), 'ʼ', ''), '$', 's'), '.', ''), ',', ''), '-', ''), '/', ''), '\', ''), '!', ''), '&', ''), '*', ''), '+', ''), ':', ''), ';', ''), '?', ''), '@', ''), '#', ''), '(', ''), ')', ''), '[', ''), ']', ''), '"', ''), '“', ''), '”', ''), '_', ''), '~', ''), '…', ''), '–', ''), '—', ''), '·', ''), '|', ''), '%', ''), '^', ''), '=', ''), '<', ''), '>', ''), ' ', '') ELSE replace(replace(replace(replace(a.name, '''', ''), '’', ''), '‘', ''), 'ʼ', '') END, 'artist', NEW.id FROM artist_alias a WHERE a.artist_id = NEW.id;
